"use client";

/**
 * StatusIsland. Work that runs in the background (an upload, an export, a
 * timer, a recording, "writing…") kept in one small floating slab: at rest a
 * pill with a lit socket and a readout; pressed, it blooms open the way every
 * Echo panel arrives, wider first and then taller, into the detail and what
 * you can do about it. It closes the other way round.
 *
 * It announces what matters and nothing else: when the work starts, finishes
 * or fails, never every percent.
 */
import {
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import { createSpring, useReducedMotionRef, type Spring } from "echo-ui-core/tactile";
import { useSoundOptional } from "echo-ui-core/sound";
import { StatusDot } from "../status-dot";
import { LcdChip } from "../lcd-chip";
import { Progress } from "../progress";
import { SizeProvider } from "../size";
import "./status-island.css";

export type StatusIslandState = "running" | "paused" | "done" | "failed";

export interface StatusIslandProps {
  /** What's happening, in a word or two: the pill's label ("Exporting", "Recording"). */
  label: string;
  /** What it's happening to, heading the open island ("Q3 report.pdf"). */
  title?: string;
  /** The pill's readout ("42%", "04:59"). Default: `progress` as a percent. */
  reading?: string;
  /** How far along, 0–1: a row of lit cells in the open island. */
  progress?: number;
  /** A line under the progress: what's left, where it went, what went wrong. */
  detail?: ReactNode;
  /** `running` (default) lights the socket; `paused` darkens it; `done` and `failed` are said out loud. */
  state?: StatusIslandState;
  /** What you can do about it: small HardwareButtons in the open island. */
  actions?: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** `inline` (default) sits where you put it; `top` and `bottom` float at the centre of that edge of the screen. */
  placement?: "inline" | "top" | "bottom";
}

const WIDE = { duration: 0.42, bounce: 0.22 };
const TALL = { duration: 0.46, bounce: 0.18 };
/** How long after it starts spreading wide it starts growing tall, and the reverse on the way back. */
const STAGGER = 120;

const WORDS: Record<StatusIslandState, string> = {
  running: "started",
  paused: "paused",
  done: "done",
  failed: "failed",
};

export function StatusIsland({
  label,
  title,
  reading,
  progress,
  detail,
  state = "running",
  actions,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  placement = "inline",
}: StatusIslandProps) {
  const [innerOpen, setInnerOpen] = useState(defaultOpen);
  const open = openProp ?? innerOpen;
  /** The open parts stay drawn until the island has closed round them. */
  const [closing, setClosing] = useState(false);
  const sound = useSoundOptional();
  const reduced = useReducedMotionRef();
  const id = useId();
  const slab = useRef<HTMLDivElement>(null);
  const toggle = useRef<HTMLButtonElement>(null);
  const width = useRef<Spring | null>(null);
  const height = useRef<Spring | null>(null);
  /** The slab's box the last time it was at rest: where a change of size starts from. */
  const rest = useRef<DOMRect | null>(null);
  const wasOpen = useRef(open);
  const timer = useRef(0);

  const setOpen = useCallback(
    (next: boolean) => {
      if (openProp === undefined) setInnerOpen(next);
      onOpenChange?.(next);
      sound?.play(next ? "transition" : "tap");
    },
    [openProp, onOpenChange, sound],
  );

  // The slab's size rides on two springs, written as variables the stylesheet reads.
  useEffect(() => {
    const el = slab.current;
    if (!el) return;
    rest.current = el.getBoundingClientRect();
    const write = (name: string) => (v: number) => el.style.setProperty(name, `${v.toFixed(1)}px`);
    width.current = createSpring(0, WIDE, write("--island-w"));
    height.current = createSpring(0, TALL, write("--island-h"));
    return () => {
      width.current?.stop();
      height.current?.stop();
      window.clearTimeout(timer.current);
    };
  }, []);

  // FLIP on size: measure where it's going, start from where it was, spring there.
  useLayoutEffect(() => {
    const el = slab.current;
    if (!el || wasOpen.current === open) return;
    wasOpen.current = open;
    const from = rest.current;
    const free = () => {
      el.removeAttribute("data-sizing");
      el.style.removeProperty("--island-w");
      el.style.removeProperty("--island-h");
      setClosing(false);
      rest.current = el.getBoundingClientRect();
    };
    if (!open) setClosing(true);
    if (reduced.current || !from || !width.current || !height.current) {
      free();
      return;
    }
    // The size it's heading for: closing, the pill alone.
    el.removeAttribute("data-sizing");
    el.toggleAttribute("data-measuring", !open);
    const to = el.getBoundingClientRect();
    el.removeAttribute("data-measuring");
    el.setAttribute("data-sizing", "");
    const w = width.current;
    const h = height.current;
    w.set(from.width);
    h.set(from.height);
    window.clearTimeout(timer.current);
    // Open: wide, then tall. Close: short, then narrow.
    const [first, firstTo, second, secondTo] = open ? [w, to.width, h, to.height] : [h, to.height, w, to.width];
    first.to(firstTo);
    timer.current = window.setTimeout(() => second.to(secondTo), STAGGER);
    const settle = window.setInterval(() => {
      if (w.moving || h.moving) return;
      window.clearInterval(settle);
      free();
    }, 60);
    return () => window.clearInterval(settle);
  }, [open, reduced]);

  // Whenever it's at rest, note its box: the next change of size starts there.
  useLayoutEffect(() => {
    const el = slab.current;
    if (el && !el.hasAttribute("data-sizing")) rest.current = el.getBoundingClientRect();
  });

  // Escape closes it, from anywhere inside.
  const onKeyDown = (e: KeyboardEvent) => {
    if (e.key === "Escape" && open) {
      e.stopPropagation();
      setOpen(false);
      toggle.current?.focus();
    }
  };

  // Said once when the work starts, finishes or fails; never every percent.
  const [said, setSaid] = useState("");
  const last = useRef(state);
  useEffect(() => {
    if (last.current === state) return;
    last.current = state;
    setSaid(`${title ?? label}: ${WORDS[state]}`);
    if (state === "done") sound?.play("notify");
    if (state === "failed") sound?.play("error");
  }, [state, title, label, sound]);

  const shown = reading ?? (progress !== undefined ? `${Math.round(Math.min(1, Math.max(0, progress)) * 100)}%` : undefined);

  return (
    <div className="echo-status-island" data-placement={placement}>
      <div
        ref={slab}
        className="echo-status-island__slab"
        data-open={open ? "" : undefined}
        data-state={state}
        onKeyDown={onKeyDown}
      >
        <button
          ref={toggle}
          type="button"
          className="echo-status-island__pill"
          aria-expanded={open}
          aria-controls={`${id}-detail`}
          // Named in full: the chip inside names itself only by its label, and
          // a name taken from content would drop the reading ("Exporting 42%").
          aria-label={shown !== undefined ? `${label} ${shown}` : undefined}
          onClick={() => setOpen(!open)}
        >
          <StatusDot on={state === "running" || state === "done"} decorative />
          <span className="echo-status-island__label">{label}</span>
          {/* A space the flex row doesn't draw, so the pill's text reads "Exporting 42%", the words of its name (BUG-317). */}
          {shown !== undefined ? <> <LcdChip value={shown} label={label} glow={state !== "paused"} /></> : null}
        </button>
        <div id={`${id}-detail`} className="echo-status-island__detail" hidden={!open && !closing}>
          {title ? <p className="echo-status-island__title">{title}</p> : null}
          {progress !== undefined ? (
            <Progress value={Math.min(1, Math.max(0, progress))} aria-label={title ?? label} cells={16} />
          ) : null}
          {detail ? <p className="echo-status-island__text">{detail}</p> : null}
          {actions ? (
            <SizeProvider size="sm">
              <div className="echo-status-island__actions">{actions}</div>
            </SizeProvider>
          ) : null}
        </div>
      </div>
      <span className="echo-status-island__said" role="status">
        {said}
      </span>
    </div>
  );
}

/**
 * StatusIsland. A floating slab, the material of everything that arrives and
 * leaves (Toast's): a pill at rest, a panel when open. While it changes size,
 * two springs write --island-w and --island-h and the slab clips to them.
 * Composes var(--echo-*) — no hex literals; the only fixed values are the
 * single-key-light occlusion model.
 */
.echo-status-island {
  display: inline-flex;
  justify-content: center;
  /* The slab is as tall as what's in it, whatever it sits in. */
  align-items: flex-start;
  align-self: start;
  max-inline-size: 100%;
  min-inline-size: 0;
}
/* Floating: centred on an edge of the screen, clear of the notch and the home bar. */
.echo-status-island[data-placement="top"],
.echo-status-island[data-placement="bottom"] {
  position: fixed;
  z-index: var(--echo-z-toast, 400);
  inset-inline: var(--echo-space-8);
  pointer-events: none;
}
.echo-status-island[data-placement="top"] {
  inset-block-start: calc(env(safe-area-inset-top, 0px) + var(--echo-space-6));
}
.echo-status-island[data-placement="bottom"] {
  inset-block-end: calc(env(safe-area-inset-bottom, 0px) + var(--echo-space-6));
  align-items: flex-end;
}
.echo-status-island[data-placement="top"] .echo-status-island__slab,
.echo-status-island[data-placement="bottom"] .echo-status-island__slab {
  pointer-events: auto;
}

.echo-status-island__slab {
  box-sizing: border-box;
  display: grid;
  max-inline-size: min(100%, 360px);
  min-inline-size: 0;
  border-radius: calc(var(--echo-control-default, 44px) / 2);
  color: var(--echo-text);
  background: linear-gradient(180deg, var(--echo-cap) 0%, var(--echo-cap-shadow) 100%);
  box-shadow: var(
    --echo-shadow-toast,
    inset 0 1.5px 0 rgb(255 255 255 / calc(0.28 * var(--echo-gloss, 1))),
    inset 0 0 0 1px color-mix(in oklab, var(--echo-seam) 70%, transparent),
    0 18px 36px -14px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.75 * var(--echo-shade, 1) * 100%), transparent),
    0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent),
    0 calc(5px * var(--echo-drawn, 0)) 0 var(--echo-line-width, 0px) var(--echo-line, transparent)
  );
  transition: border-radius var(--echo-duration-sweep) var(--echo-ease-glide);
}
.echo-status-island__slab[data-open] {
  inline-size: min(100vw - 2 * var(--echo-space-8), 340px);
  border-radius: var(--echo-radius-3xl);
}
/* While it changes size, the springs decide it and the slab clips to them. */
.echo-status-island__slab[data-sizing] {
  inline-size: var(--island-w);
  block-size: var(--island-h);
  overflow: hidden;
}
.echo-status-island__slab[data-measuring] {
  inline-size: auto;
}
.echo-status-island__slab[data-measuring] .echo-status-island__detail {
  display: none;
}

/* The pill: a lit socket, the label, a small screen. It opens and closes the island. */
.echo-status-island__pill {
  display: flex;
  align-items: center;
  gap: var(--echo-space-5);
  min-inline-size: 0;
  min-block-size: var(--echo-control-default, 44px);
  padding-block: var(--echo-space-2);
  padding-inline: var(--echo-space-8) var(--echo-space-2);
  border: 0;
  border-radius: inherit;
  background: none;
  color: inherit;
  cursor: pointer;
  text-align: start;
  outline: none;
}
/* Open, the pill is the panel's top row: even insets, clear of its rounded corners. */
.echo-status-island__slab[data-open] .echo-status-island__pill {
  padding-block: var(--echo-space-5) 0;
  padding-inline: var(--echo-space-8) var(--echo-space-6);
}
.echo-status-island__pill:focus-visible {
  box-shadow: var(--echo-shadow-ring-inset, inset 0 0 0 2px var(--echo-accent-ink, var(--echo-accent-glow)));
}
.echo-status-island__label {
  flex: 1 1 auto;
  min-inline-size: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-3xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-widest, 0.25em);
  text-transform: uppercase;
}
/* The readout's own label repeats the pill's, so the chip shows its value alone. */
.echo-status-island__pill .echo-lcd-chip {
  flex: none;
  padding-block: var(--echo-space-2);
}
.echo-status-island__pill .echo-lcd-chip__label {
  display: none;
}
.echo-status-island__pill .echo-lcd-chip__value {
  font-size: var(--echo-text-lg);
}
.echo-status-island__pill:not(:has(.echo-lcd-chip)) {
  padding-inline-end: var(--echo-space-8);
}

.echo-status-island__detail {
  display: grid;
  gap: var(--echo-space-5);
  padding: var(--echo-space-2) var(--echo-space-8) var(--echo-space-8);
  min-inline-size: 0;
}
.echo-status-island__detail[hidden] {
  display: none;
}
.echo-status-island__title {
  margin: 0;
  font-family: var(--echo-font-sans, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-lg);
  font-weight: var(--echo-weight-semibold, 600);
  line-height: var(--echo-leading-tight, 1.25);
  overflow-wrap: anywhere;
}
.echo-status-island__text {
  margin: 0;
  font-family: var(--echo-font-sans, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-sm);
  line-height: var(--echo-leading-snug, 1.4);
  color: var(--echo-text-dim);
}
.echo-status-island__actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: var(--echo-space-4);
}

.echo-status-island__said {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@media (prefers-reduced-motion: reduce) {
  .echo-status-island__slab {
    transition: none;
  }
}
@media (forced-colors: active) {
  .echo-status-island__slab {
    border: var(--echo-border-hairline, 1px) solid CanvasText;
  }
  /* Open, the pill is the panel's top row: even insets, clear of its rounded corners. */
.echo-status-island__slab[data-open] .echo-status-island__pill {
  padding-block: var(--echo-space-5) 0;
  padding-inline: var(--echo-space-8) var(--echo-space-6);
}
.echo-status-island__pill:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -3px;
  }
}
